const LAMP_IMG="data:image/png;base64,";
const OPT_NAMES = ["コインMAX","1つ抜き","2つ抜き","3つ抜き","4つ抜き","5つ抜き"];
const HOUJOU = "";
const esc = s => String(s).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const fmt = n => n.toLocaleString("ja-JP");
const approx = n => "約" + fmt(Math.round(n/10)*10);
const PERS={"乾燥機":"N","ミル":"T","煮込み鍋":"T","作業台":"J","コンロ":"S","かまど":"N","漬け込み樽":"P","糸車":"F","木工台":"E","煙突鍛造炉":"S","醸造樽":"E","調香台":"I"};
function occHTML(rows){
  const G=[];rows.forEach(r=>{const l=G[G.length-1];if(l&&l.f===r.fac)l.rs.push(r);else G.push({f:r.fac,rs:[r]});});
  const tg=t=>t?`<span class="tag ${t[0]}">${t[1]}</span>`:"";
  return G.map(g=>`<div class="row proc"><div class="p">${esc(g.f)}</div><div class="to">${g.rs.map(r=>`<div class="unit"><div>${r.lv?`<span class="lvb">Lv.${r.lv}</span>`:""}<span class="cnt">×${r.n}</span>${ENVT[r.p]&&/ヒーター|クーラー|日光ランプ/.test(g.f)?et(r.p):esc(r.p)}${tg(r.tag)}${tg(r.tag2)}${envT(r.sub)}</div>${subH(r.sub)}</div>`).join("")}</div></div>`).join("");
}
const ENVT={"暖かい":"warm","猛暑":"hot","涼しい":"cool","凍結":"frozen","十分な日光":"sun"};
function et(m){return `<span class="tag env ${ENVT[m]||""}">${esc(m)}</span>`;}
function envParse(sub){ let t="", q=sub||"";
  q=q.replace(/ヒーター\((.+?)\)とクーラー\((.+?)\)の(?:範囲が重なる|両方の範囲にかかる)所に(?:置く|植える)\((.+?)になる\)。?/g,(m,a,b,c)=>{t+=`${et(a)}<span class="envop">+</span>${et(b)}<span class="envop">=</span>${et(c)}`;return "";});
  q=q.replace(/(?:ヒーター|クーラー|日光ランプ)\((.+?)\)の範囲内に(?:置く|植える)。?/g,(m,a)=>{t+=et(a);return "";});
  q=q.replace(/日光ランプの範囲内に(?:置く|植える)。?/g,()=>{t+=et("十分な日光");return "";});
  q=q.replace(/^雷のホーム能力(?:Lv\d+以上)?のアニモを1本に1体ずつ置き、/,"").replace(/^雷のホーム能力(?:Lv\d+以上)?のアニモを置く。/,"").replace(/^。/,"");
  return {t,q};
}
function envT(sub){const {t}=envParse(sub); return t?`<span class="envs">${t}</span>`:"";}   // 11/4 環境タグは名前と同じ行に
function subH(sub){const {q}=envParse(sub); return q?`<span class="sub">${q.split("「電力」").map(esc).join(`<span class="tag pw">電力</span>`)}</span>`:"";}
function rowHTML(r){
  const chain = (r.to||[]).map(([x,f])=>`${esc(x)}${f?`<span class="fac">(${esc(f)})</span>`:""}`).join(' <span class="arrow">→</span> ');
  const tag = r.tag?`<span class="tag ${r.tag[0]}">${r.tag[1]}</span>`:"";
  const name = r.fac?`<span style="color:var(--muted);font-weight:500;font-size:.85em">${esc(r.fac)}${r.lv?` Lv.${r.lv}`:""}</span><br>${ENVT[r.p]&&/ヒーター|クーラー|日光ランプ/.test(r.fac)?et(r.p):esc(r.p)}`:esc(r.p);
  const tag2 = r.tag2?`<span class="tag ${r.tag2[0]}">${r.tag2[1]}</span>`:"";
  return `<div class="row"><div class="p">${name}${tag}${tag2}${envT(r.sub)}</div><div class="n">${r.n}</div><div class="to">${chain?'<span class="arrow">→ </span>'+chain:""}${subH(r.sub)}</div></div>`;
}
(function(){
  const root=document.documentElement, btn=document.getElementById("theme-btn");
  const sun='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/></svg>';
  const moon='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 12.8A9 9 0 1 1 11.2 3a7 7 0 0 0 9.8 9.8z"/></svg>';
  const sysDark=()=>matchMedia("(prefers-color-scheme: dark)").matches;
  const cur=()=>root.dataset.theme||(sysDark()?"dark":"light");
  function paint(){const d=cur()==="dark"; btn.innerHTML=(d?sun:moon)+(d?"ライト":"ダーク");}
  try{const t=localStorage.getItem("aniimo-theme"); if(t==="dark"||t==="light") root.dataset.theme=t;}catch(e){}
  paint();
  btn.addEventListener("click",()=>{const next=cur()==="dark"?"light":"dark"; root.dataset.theme=next; try{localStorage.setItem("aniimo-theme",next);}catch(e){} paint();});
  try{matchMedia("(prefers-color-scheme: dark)").addEventListener("change",()=>{if(!root.dataset.theme) paint();});}catch(e){}
})();
let state={lv:"21",k:0};
try{const s=JSON.parse(localStorage.getItem("aniimo-home3")||"null"); if(s&&D[s.lv]&&D[s.lv].opts[s.k]) state=s;}catch(e){}
const D0=Object.assign({},D); function applyNF(){const S=state.nf?DN:D0; for(const k in S) D[k]=S[k];} const NF_END=new Date(2026,11,10,8).getTime(); if(Date.now()>=NF_END&&!(state.nfAt>=NF_END)) state.nf=true; else if(Date.now()<NF_END&&!(state.nfAt>=new Date(2026,9,29,10).getTime())) state.nf=false;   /* 10/30 イベント期間中はイベント対応から(10/29 10:00 以降にボタンで選んだ場合はそれを優先) */ applyNF();
