document.getElementById("seg-level").addEventListener("click",e=>{const b=e.target.closest("button");if(b){if(state.lv!==b.dataset.lv){state.alt2=false; state.alt=false;} state.lv=b.dataset.lv; if(!D[state.lv].opts[state.k]) state.k=D[state.lv].opts.length-1; render();}});
document.getElementById("view").addEventListener("change",e=>{const c=e.target.closest("input[data-chk]");if(c){if(/^ev\d$/.test(c.dataset.chk)){state.ev=c.checked?+c.dataset.chk.slice(2):0;} else if(c.dataset.chk==="alt") state.alt=c.checked; else state.alt2=c.checked;render();}});
document.getElementById("view").addEventListener("click",e=>{const a=e.target.closest(".altsw button");if(a&&a.dataset.rbv!==undefined){state.rbv=a.dataset.rbv;render();return;}if(a&&a.dataset.ev!==undefined){state.ev=+a.dataset.ev;render();return;}if(a&&a.dataset.nf!==undefined){state.nf=a.dataset.nf==="1";state.nfAt=Date.now();applyNF();if(!D[state.lv].opts[state.k])state.k=0;render();return;}if(a&&a.dataset.dm!==undefined){state.dm=a.dataset.dm;state.k=0;render();return;}if(a&&a.dataset.dl!==undefined){state.dl=a.dataset.dl==="1";state.k=0;render();return;}if(a){if(a.dataset.alt2!==undefined) state.alt2=a.dataset.alt2==="1"; else state.alt=a.dataset.alt==="1";render();return;}const b=e.target.closest(".opt");if(b){state.k=+b.dataset.k;render();const t=document.getElementById("result");if(t&&window.innerWidth<700){const y=t.getBoundingClientRect().top+window.scrollY-document.querySelector(".controls").offsetHeight-8;window.scrollTo({top:y,behavior:matchMedia("(prefers-reduced-motion: reduce)").matches?"auto":"smooth"});}}});
const GFIG={
  lv:()=>document.querySelector(".controls"),
  dl:()=>document.querySelector("#view .altsw:not(.dmsw):not(.nfsw):not(.evsw):not(.rbsw)"),
  dm:()=>document.querySelector("#view .dmsw")||(()=>{const d=document.createElement("div");d.className="seg altsw dmsw";d.innerHTML=DMODES.map((m,i)=>`<button type="button" aria-pressed="${i===0}">${m[1].replace(/(で|を|も)/,"$1<br>")}</button>`).join("");return d;})(),
  opts:()=>{const o=document.querySelector("#opts");if(!o)return null;const c=o.cloneNode(true);[...c.children].slice(2).forEach(x=>x.remove());return c;},
  chk:()=>{const p=document.querySelector("#view .pre"),l=document.querySelector("#view label.unlk");if(!p&&!l){const L=D["14"].alt;const d=document.createElement("div");d.innerHTML=`<p class="pre">${esc(L.pre)}</p><label class="unlk"><input type="checkbox"> ${esc(L.chk)}</label>`;return d;}const d=document.createElement("div");if(p)d.appendChild(p.cloneNode(true));if(l)d.appendChild(l.cloneNode(true));return d;},
  table:()=>{const a=document.querySelectorAll("#view section.area")[1];if(!a)return null;const c=a.cloneNode(true);c.querySelectorAll(".row").forEach((r,i)=>{if(i>=2)r.remove();});return c;},
  team:()=>{const t=document.querySelector("#team .toolbtn");return t;}
};
function buildGuideFigs(){
  const g=document.getElementById("guide"); if(!g||!g.open) return;
  g.querySelectorAll(".gfig[data-fig]").forEach(f=>{let el;try{el=GFIG[f.dataset.fig]();}catch(e){el=null;}
    f.innerHTML=""; if(!el) return; const c=el.cloneNode(true);
    c.querySelectorAll("[id]").forEach(x=>x.removeAttribute("id")); c.removeAttribute&&c.removeAttribute("id");
    c.querySelectorAll(".gl,.here").forEach(x=>x.remove());
    c.querySelectorAll("button,input,a").forEach(x=>{x.tabIndex=-1;if(x.tagName==="A")x.removeAttribute("href");["data-dl","data-dm","data-lv","data-chk","data-k","data-here"].forEach(k=>x.removeAttribute(k));});
    f.appendChild(c);});
}
document.getElementById("guide").addEventListener("toggle",buildGuideFigs);
const HERE={g1:"#seg-level",g2:"#view .altsw:not(.dmsw):not(.nfsw):not(.evsw):not(.rbsw)",g3:"#view .dmsw",g4:"#opts",g5:"#view .pre, #view label.unlk",g6:"#view section.area:nth-of-type(2)"};
