  if(k==="g4"&&!document.querySelector(HERE.g4)){state.dl=false;state.k=0;render();}
  let t=document.querySelector(HERE[k]); if(!t&&k==="g5") t=document.querySelector("#opts")||document.querySelector("#view .area");
  if(k==="g6") t=document.querySelectorAll("#view section.area")[1]||t;
  if(!t) return;
  t.scrollIntoView({behavior:matchMedia("(prefers-reduced-motion: reduce)").matches?"auto":"smooth",block:"center"});
