function subst(v,nums){return v.replace(/\{(\d+)(?:\|(\w+))?\}/g,(x,i,mod)=>{const m=nums[+i]; if(m===undefined) return x; if(mod==="raw") return m; if(mod==="man") return fmtNum(m,10000); if(mod==="mil") return (parseFloat(m.replace(/,/g,""))/100).toLocaleString(LANG==="es"?"es-ES":"en-US",{maximumFractionDigits:2}); return fmtNum(m);});}
