function look0(raw){const [k,nums]=norm(raw); const d=DICT[LANG]||{}; let v=d[k]; if(v===undefined){ if(raw.includes("<br>")){const ps=raw.split("<br>"); const tr=ps.map(p=>{const [k2,n2]=norm(p); const v2=d[k2]; return v2===undefined?(JP.test(k2)?null:p):subst(v2,n2);}); if(tr.every(x=>x!==null)) return tr.join("<br>");} if(JP.test(k)) miss.add(k); return null;} return subst(v,nums);}   // 10/14 <br> で区切った行は1行ずつでも訳す
